//! Library-level checks on the committed datasets (tests/data/README.md), against the papers
//! where they report a value (Tharanga et al. 2025; Wu 2025 for similarity-weighted entropy;
//! see docs, "Comparison with the papers").
//! Entropies are compared with the output of the independent reference implementation in
//! `paper_expected` (generated by `scripts/reference/paper_values.py`, checked in CI), other
//! numbers with their closed forms, both with `common::assert_agrees` (relative 1e-13), the rule
//! of the live differential test.

use std::path::PathBuf;

use dima_core::analyze;
use dima_core::config::{Alphabet, AnalysisParams, Percent};
use dima_core::control::RunControl;
use dima_core::hcs::{self, HcsParams};
use dima_core::input::Source;
use dima_core::model::{Extremum, Motif, Results};
use paper_expected::{Position, SimilarityPosition, SimilaritySummary, Summary};

mod common;
mod paper_expected;

fn data(path: &str) -> Source {
    Source::Path(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(path),
    )
}

fn run(path: &str, params: AnalysisParams) -> Results {
    analyze(&data(path), &params, &RunControl::new())
        .unwrap()
        .results
}

#[track_caller]
fn close(got: f64, want: f64) {
    common::assert_agrees("value", got, want);
}

#[track_caller]
fn extremum(got: Option<Extremum>, entropy: f64, position: u64, ties: u64) {
    let e = got.expect("extremum present");
    close(e.entropy, entropy);
    assert_eq!((e.position, e.tied_position_count), (position, ties));
}

/// The means and extremes of `r`; `lowest` and `highest` are (position, tied positions).
#[track_caller]
fn summary(r: &Results, want: &Summary, lowest: (u64, u64), highest: (u64, u64)) {
    close(r.average_entropy.unwrap(), want.mean);
    close(
        r.all_positions_summary.average_entropy.unwrap(),
        want.all_mean,
    );
    extremum(r.lowest_entropy, want.lowest, lowest.0, lowest.1);
    extremum(r.highest_entropy, want.highest, highest.0, highest.1);
}

/// The similarity-weighted summary of `r`, which must have been computed.
#[track_caller]
fn similarity(r: &Results, want: &SimilaritySummary, lowest: (u64, u64), highest: (u64, u64)) {
    let s = r
        .similarity_weighted_entropy_summary
        .as_ref()
        .expect("similarity-weighted entropy computed");
    close(s.average_entropy.unwrap(), want.mean);
    close(s.average_observed_entropy.unwrap(), want.observed_mean);
    extremum(s.lowest_entropy, want.lowest, lowest.0, lowest.1);
    extremum(s.highest_entropy, want.highest, highest.0, highest.1);
}

/// The similarity-weighted values of position `p`.
#[track_caller]
fn similarity_position(p: &dima_core::model::PositionResult, want: &SimilarityPosition) {
    close(
        p.similarity_weighted_entropy.unwrap(),
        want.similarity_weighted,
    );
    close(
        p.normalised_observed_entropy.unwrap(),
        want.normalised_observed,
    );
    close(
        p.normalised_similarity_weighted_entropy.unwrap(),
        want.normalised_similarity_weighted,
    );
}

/// Every run below computes similarity-weighted entropy except T = 30, which checks that it is
/// then absent (`paper_values.py` runs the reference the same way).
fn with_similarity() -> AnalysisParams {
    AnalysisParams {
        similarity_weighted_entropy: true,
        ..AnalysisParams::default()
    }
}

fn labels(r: &Results) -> (u64, u64, u64, u64) {
    let c = r.support_label_counts;
    (c.no_support, c.low, c.equal_to_threshold, c.eligible)
}

#[test]
fn mers_spike_protein() {
    for (t, want, pos25) in [
        (
            30,
            &paper_expected::MERS_AA_T30,
            &paper_expected::MERS_AA_T30_POS25,
        ),
        (
            100,
            &paper_expected::MERS_AA_T100,
            &paper_expected::MERS_AA_T100_POS25,
        ),
    ] {
        let r = run(
            "samples/mers_spike_aa.fasta",
            AnalysisParams {
                support_threshold: Some(t),
                similarity_weighted_entropy: t == 100,
                ..AnalysisParams::default()
            },
        );
        assert_eq!(r.sequence_count, 191);
        assert_eq!(r.kmer_length, 9);
        assert_eq!(r.position_count, 1345);
        assert_eq!(labels(&r), (0, 0, 0, 1345));
        summary(&r, want, (7, 455), (26, 1));
        assert_eq!(r.query_name, "mers_spike_aa");
        // Position 25 (the paper's Fig. 1C).
        let p = &r.results[24];
        assert_eq!(p.position, 25);
        assert_eq!(p.support, 170);
        let counts: Vec<u64> = p.diversity_motifs.iter().map(|v| v.count).collect();
        assert_eq!(counts, [129, 14, 9, 6, 4, 4, 1, 1, 1, 1]);
        assert_eq!(p.diversity_motifs[0].sequence, "SVKSACIEV");
        assert_eq!(p.diversity_motifs[0].motif, Motif::Index);
        assert_eq!(p.diversity_motifs[1].sequence, "SFKSACIEV");
        assert_eq!(p.diversity_motifs[1].motif, Motif::Major);
        assert_eq!(p.distinct_variants_count, 9);
        close(p.distinct_variants_incidence.unwrap(), 900.0 / 41.0);
        let Position {
            entropy,
            observed,
            coverage,
        } = pos25;
        close(p.entropy.unwrap(), *entropy);
        close(p.observed_entropy.unwrap(), *observed);
        close(p.sample_coverage.unwrap(), *coverage);
        if t == 100 {
            similarity(
                &r,
                &paper_expected::MERS_AA_T100_SIMILARITY,
                (7, 455),
                (26, 1),
            );
            similarity_position(p, &paper_expected::MERS_AA_T100_POS25_SIMILARITY);
        } else {
            assert!(r.similarity_weighted_entropy_summary.is_none());
            assert!(r.results.iter().all(|q| {
                q.similarity_weighted_entropy.is_none()
                    && q.normalised_observed_entropy.is_none()
                    && q.normalised_similarity_weighted_entropy.is_none()
            }));
        }
    }
}

#[test]
fn mers_spike_protein_hcs() {
    let r = run("samples/mers_spike_aa.fasta", AnalysisParams::default());
    let h = hcs::compute(&r, &HcsParams::default()).unwrap();
    assert_eq!(h.region_count, 44);
    assert_eq!(h.flagged_region_count, 0);
    assert_eq!(
        (h.regions[0].start_column, h.regions[0].end_column),
        (7, 22)
    );
}

#[test]
fn mers_spike_nucleotide() {
    let r = run("tests/data/MERS_Spike_nt.fasta.bz2", with_similarity());
    assert_eq!(r.kmer_length, 27);
    assert_eq!(r.position_count, 4039);
    assert_eq!(labels(&r), (0, 29, 0, 4010));
    summary(&r, &paper_expected::MERS_NT, (18, 63), (1415, 2));
    similarity(&r, &paper_expected::MERS_NT_SIMILARITY, (18, 63), (2835, 1));
    let h = hcs::compute(&r, &HcsParams::default()).unwrap();
    assert_eq!((h.region_count, h.flagged_region_count), (10, 1));
    let f = h.regions.iter().find(|r| r.flagged).unwrap();
    assert_eq!((f.start_column, f.end_column, f.length), (3518, 3572, 55));
    assert_eq!(f.min_support, 2);
    assert_eq!(f.low_support_positions.len(), 29);
    close(f.conservation_lower_bound_95, 0.025f64.sqrt());
    let e = hcs::compute(
        &r,
        &HcsParams {
            eligible_only: true,
            ..HcsParams::default()
        },
    )
    .unwrap();
    assert_eq!((e.region_count, e.flagged_region_count), (9, 0));
}

#[test]
fn hiv_pol_protein() {
    let r = run(
        "tests/data/HIV1_ALL_2020_pol_PRO.fasta.bz2",
        with_similarity(),
    );
    assert_eq!(r.sequence_count, 3756);
    assert_eq!(r.position_count, 1189);
    assert_eq!(labels(&r), (551, 162, 0, 476));
    summary(&r, &paper_expected::HIV_PRO, (433, 1), (772, 1));
    similarity(&r, &paper_expected::HIV_PRO_SIMILARITY, (433, 1), (772, 1));
    let h = hcs::compute(&r, &HcsParams::default()).unwrap();
    assert_eq!((h.region_count, h.flagged_region_count), (1, 1));
    let g = &h.regions[0];
    assert_eq!((g.start_column, g.end_column, g.min_support), (373, 381, 3));
    close(g.conservation_lower_bound_95, 0.025f64.powf(1.0 / 3.0));
    let e = hcs::compute(
        &r,
        &HcsParams {
            eligible_only: true,
            ..HcsParams::default()
        },
    )
    .unwrap();
    assert_eq!(e.region_count, 0);
}

#[test]
fn hiv_pol_dna_reproduces_the_paper() {
    let r = run(
        "tests/data/HIV1_FLT_2022_pol_DNA.fasta.bz2",
        with_similarity(),
    );
    assert_eq!(r.sequence_count, 2637);
    // Paper: 3,364 positions, 564 LS, 680 NS; mean ≈ 5.35 bits.
    assert_eq!(r.position_count, 3364);
    assert_eq!(labels(&r), (680, 564, 0, 2120));
    summary(&r, &paper_expected::HIV_DNA, (3046, 2), (2176, 1));
    similarity(
        &r,
        &paper_expected::HIV_DNA_SIMILARITY,
        (3046, 2),
        (2176, 1),
    );
    let threshold: Percent = "70".parse().unwrap();
    for eligible_only in [false, true] {
        let h = hcs::compute(
            &r,
            &HcsParams {
                threshold,
                eligible_only,
            },
        )
        .unwrap();
        let spans: Vec<(u64, u64)> = h
            .regions
            .iter()
            .map(|g| (g.start_column, g.end_column))
            .collect();
        assert_eq!(
            spans,
            [(3046, 3077), (3156, 3185)],
            "eligible_only={eligible_only}"
        );
        assert!((h.regions[0].min_incidence - 80.10).abs() < 0.005);
        assert!((h.regions[0].conservation_lower_bound_95 - 0.7852).abs() < 5e-5);
        assert!((h.regions[1].min_incidence - 71.53).abs() < 0.005);
        assert!((h.regions[1].conservation_lower_bound_95 - 0.6976).abs() < 5e-5);
    }
}

/// Wu 2025's ToBRFV samples (Supplementary File 2: the unique 120-nt sequences of the 5'-120nts
/// region with their read counts; tests/data/README.md): one 120-mer position each. With the
/// published data the observed entropy is higher in the Tm-2² sample than in tm-2, the reverse
/// of Wu's Section 3.3 (documented on "Comparison with the papers").
#[test]
fn wu_tobrfv_samples() {
    let params = AnalysisParams {
        alphabet: Some(Alphabet::Dna),
        kmer_length: Some(120),
        ..with_similarity()
    };
    let mut observed = Vec::new();
    for (path, reads, distinct, want, pos, sim, sim_pos) in [
        (
            "tests/data/tobrfv_tm2.fasta.bz2",
            10_833,
            48,
            &paper_expected::TOBRFV_TM2,
            &paper_expected::TOBRFV_TM2_POS1,
            &paper_expected::TOBRFV_TM2_SIMILARITY,
            &paper_expected::TOBRFV_TM2_POS1_SIMILARITY,
        ),
        (
            "tests/data/tobrfv_tm22.fasta.bz2",
            6_969,
            47,
            &paper_expected::TOBRFV_TM22,
            &paper_expected::TOBRFV_TM22_POS1,
            &paper_expected::TOBRFV_TM22_SIMILARITY,
            &paper_expected::TOBRFV_TM22_POS1_SIMILARITY,
        ),
    ] {
        let r = run(path, params.clone());
        assert_eq!((r.sequence_count, r.position_count), (reads, 1));
        let p = &r.results[0];
        assert_eq!((p.support, p.diversity_motifs.len()), (reads, distinct));
        summary(&r, want, (1, 1), (1, 1));
        close(p.observed_entropy.unwrap(), pos.observed);
        similarity(&r, sim, (1, 1), (1, 1));
        similarity_position(p, sim_pos);
        observed.push(p.observed_entropy.unwrap());
    }
    assert!(observed[1] > observed[0]);
}

/// One position of `variants` (k-mer, count), analysed with the given alphabet.
fn pool(variants: &[(Vec<u8>, u64)], alphabet: Alphabet) -> dima_core::model::PositionResult {
    let mut fasta = Vec::new();
    for (i, (kmer, count)) in variants.iter().enumerate() {
        for j in 0..*count {
            fasta.extend_from_slice(format!(">v{i}_{j}\n").as_bytes());
            fasta.extend_from_slice(kmer);
            fasta.push(b'\n');
        }
    }
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("pool.fasta");
    std::fs::write(&path, fasta).unwrap();
    let k = variants[0].0.len();
    let params = AnalysisParams {
        alphabet: Some(alphabet),
        kmer_length: Some(k),
        support_threshold: Some(1),
        ..with_similarity()
    };
    let mut r = analyze(&Source::Path(path), &params, &RunControl::new())
        .unwrap()
        .results;
    assert_eq!(r.results.len(), 1);
    r.results.remove(0)
}

/// Wu's saturated pools: every k-mer with m free sites (Fig. 4: m = k; Fig. 5c: four free sites
/// in a 6-mer), each once. The weights are 4^-m + 3m/(4k), so the values are exact.
#[test]
fn wu_saturated_pools() {
    let saturated = |m: u32, k: usize, letters: &[u8]| -> Vec<(Vec<u8>, u64)> {
        (0..4usize.pow(m))
            .map(|mut x| {
                let mut kmer = vec![letters[0]; k];
                for site in kmer.iter_mut().take(m as usize) {
                    *site = letters[x % 4];
                    x /= 4;
                }
                (kmer, 1)
            })
            .collect()
    };
    for k in 1..=7usize {
        let p = pool(&saturated(k as u32, k, b"ACGT"), Alphabet::Dna);
        let w = 0.25f64.powi(k as i32) + 0.75;
        assert_eq!(
            p.similarity_weighted_entropy,
            Some(2.0 * k as f64 * w),
            "k = {k}"
        );
        assert_eq!(p.normalised_similarity_weighted_entropy, Some(w), "k = {k}");
        assert_eq!(p.normalised_observed_entropy, Some(1.0), "k = {k}");
    }
    // Fig. 5c: H = 8, H_sim = 129/32 = 4.03125 and H_nsim = 129/256 (printed 4.04 and 0.50).
    let p = pool(&saturated(4, 6, b"ACGU"), Alphabet::Rna);
    assert_eq!(p.observed_entropy, Some(8.0));
    assert_eq!(p.similarity_weighted_entropy, Some(129.0 / 32.0));
    assert_eq!(
        p.normalised_similarity_weighted_entropy,
        Some(129.0 / 256.0)
    );
}

/// Wu's Supplementary File 1, sheet "Figure 2 Extended Data": five populations of ten variants
/// whose every pair has the same similarity s, with the four metrics printed to five decimals.
/// Built as protein 1,000-mers in which every pair differs at (1 - s)·1000 sites.
#[test]
fn wu_supplementary_file_1() {
    // (frequencies × 100; [(s, H, H_n, H_sim, H_nsim)]).
    type Row = (f64, f64, f64, f64, f64);
    let populations: [([u64; 10], [Row; 4]); 5] = [
        (
            [70, 5, 5, 5, 5, 2, 2, 2, 2, 2],
            [
                (0.999, 1.78897, 0.53853, 0.30813, 0.09276),
                (0.9, 1.78897, 0.53853, 0.45488, 0.13693),
                (0.5, 1.78897, 0.53853, 1.04781, 0.31542),
                (0.001, 1.78897, 0.53853, 1.78749, 0.53809),
            ],
        ),
        (
            [60, 10, 10, 4, 4, 4, 2, 2, 2, 2],
            [
                (0.999, 2.11534, 0.63678, 0.36482, 0.10982),
                (0.9, 2.11534, 0.63678, 0.53829, 0.16204),
                (0.5, 2.11534, 0.63678, 1.23920, 0.37304),
                (0.001, 2.11534, 0.63678, 2.11358, 0.63625),
            ],
        ),
        (
            [40, 30, 10, 10, 2, 2, 2, 2, 1, 1],
            [
                (0.999, 2.29863, 0.69196, 0.44649, 0.13441),
                (0.9, 2.29863, 0.69196, 0.63003, 0.18966),
                (0.5, 2.29863, 0.69196, 1.37163, 0.41290),
                (0.001, 2.29863, 0.69196, 2.29678, 0.69140),
            ],
        ),
        (
            [30, 30, 20, 10, 2, 2, 2, 2, 1, 1],
            [
                (0.999, 2.42314, 0.72944, 0.45108, 0.13579),
                (0.9, 2.42314, 0.72944, 0.64651, 0.19462),
                (0.5, 2.42314, 0.72944, 1.43613, 0.43232),
                (0.001, 2.42314, 0.72944, 2.42117, 0.72884),
            ],
        ),
        (
            [20, 20, 20, 10, 10, 10, 5, 3, 1, 1],
            [
                (0.999, 2.89048, 0.87012, 0.39747, 0.11965),
                (0.9, 2.89048, 0.87012, 0.64453, 0.19402),
                (0.5, 2.89048, 0.87012, 1.64273, 0.49451),
                (0.001, 2.89048, 0.87012, 2.88798, 0.86937),
            ],
        ),
    ];
    const K: usize = 1000;
    let printed = |got: Option<f64>, want: f64, what: &str| {
        let got = got.unwrap();
        assert!(
            (got - want).abs() <= 5e-6,
            "{what}: {got} vs printed {want}"
        );
    };
    for (counts, rows) in populations {
        for (s, h, hn, hsim, hnsim) in rows {
            let differing = ((1.0 - s) * K as f64).round() as usize;
            let variants: Vec<(Vec<u8>, u64)> = counts
                .iter()
                .zip(b"CDEFGHIKLM")
                .map(|(&c, &letter)| {
                    let mut kmer = vec![b'A'; K];
                    kmer[..differing].fill(letter);
                    (kmer, c)
                })
                .collect();
            let p = pool(&variants, Alphabet::Protein);
            let what = format!("{counts:?} at s = {s}");
            printed(p.observed_entropy, h, &what);
            printed(p.normalised_observed_entropy, hn, &what);
            printed(p.similarity_weighted_entropy, hsim, &what);
            printed(p.normalised_similarity_weighted_entropy, hnsim, &what);
        }
    }
}
